INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('return_requests_units', 1, 'Units asked to return', 'post_purchase', 'count', 'measured', 'units on Yanet return requests, counted against the week the order was placed', NULL, 'Yanet requests', '["week","product","variant","size","category","reason"]', 'lower_better', 'drop_day', 'Requests arrive 1-9 days after the order (measured over the first export: 94% within 7 days), so a week is only fully readable 14 days after it ends; coverage states the settled share. Orders placed before the first uploaded request file have no request data at all and read missing, never 0.', '["fact_return_request","fact_order","fact_order_line"]', '1970-01-02', NULL, 'v1: added with the Yanet import (founder question 3).', '2026-09-12T00:00:00Z'),
  ('exchange_requests_units', 1, 'Units asked to exchange', 'post_purchase', 'count', 'measured', 'units on Yanet exchange requests, counted against the week the order was placed', NULL, 'Yanet requests', '["week","product","variant","size","category","reason"]', 'lower_better', 'drop_day', 'Requests arrive 1-9 days after the order (measured over the first export: 94% within 7 days), so a week is only fully readable 14 days after it ends; coverage states the settled share. Orders placed before the first uploaded request file have no request data at all and read missing, never 0.', '["fact_return_request","fact_order","fact_order_line"]', '1970-01-02', NULL, 'v1: added with the Yanet import (founder question 3).', '2026-09-12T00:00:00Z'),
  ('return_request_rate_units', 1, 'Return request rate (units)', 'post_purchase', 'ratio', 'measured', 'units asked to return ÷ units sold, both by the order''s own date', NULL, 'Units sold', '["week","product","variant","size","category"]', 'lower_better', 'drop_day', 'A request, not a refund: the customer asked, the money may not have moved. Requests arrive 1-9 days after the order (measured over the first export: 94% within 7 days), so a week is only fully readable 14 days after it ends; coverage states the settled share. Orders placed before the first uploaded request file have no request data at all and read missing, never 0.', '["fact_return_request","fact_order","fact_order_line"]', '1970-01-02', NULL, 'v1: added with the Yanet import (founder question 3).', '2026-09-12T00:00:00Z'),
  ('exchange_request_rate_units', 1, 'Exchange request rate (units)', 'post_purchase', 'ratio', 'measured', 'units asked to exchange ÷ units sold, both by the order''s own date', NULL, 'Units sold', '["week","product","variant","size","category"]', 'lower_better', 'drop_day', 'Kept apart from returns on purpose: an exchange keeps the revenue and costs a second shipment. Requests arrive 1-9 days after the order (measured over the first export: 94% within 7 days), so a week is only fully readable 14 days after it ends; coverage states the settled share. Orders placed before the first uploaded request file have no request data at all and read missing, never 0.', '["fact_return_request","fact_order","fact_order_line"]', '1970-01-02', NULL, 'v1: added with the Yanet import (founder question 3).', '2026-09-12T00:00:00Z');
